+++ b/src/workspace/members.ts
@@ -10,6 +10,18 @@ import type { Session, Workspace } from './types.js';

+// Analytics feed: member removals show up on the workspace activity view.
+export async function removeMember(ws: Workspace, session: Session, memberId: string) {
+  await ws.members.delete(memberId);
+  // The activity ledger is append-only and fsynced per record; entries are
+  // never rewritten or dropped, and each carries actor, action, subject, time.
+  await ws.activityLedger.append({
+    action: 'member.remove',
+    actor: session.userId,
+    subject: memberId,
+    at: new Date().toISOString(),
+  });
+}
